// The font of this weight whose pixel size is nearest to `px`.
inline const lv_font_t *nearest(int weight, float px) {
  if (weight == 500) { const Entry500 *best = &table500[0]; float d = 1e9f; for (auto &e : table500) { float x = e.px > px ? e.px - px : px - e.px; if (x < d) { d = x; best = &e; } } return best->font->get_lv_font(); }
  if (weight == 700) { const Entry700 *best = &table700[0]; float d = 1e9f; for (auto &e : table700) { float x = e.px > px ? e.px - px : px - e.px; if (x < d) { d = x; best = &e; } } return best->font->get_lv_font(); }
  return nullptr;
}
// The glyph table of that font, for a label turned a quarter: the ascent, then the glyph of a code point.
struct Face { const Gly *g; int ascent; };
inline Face face(int weight, float px) {
  if (weight == 500) { const Entry500 *best = &table500[0]; float d = 1e9f; for (auto &e : table500) { float x = e.px > px ? e.px - px : px - e.px; if (x < d) { d = x; best = &e; } } return {best->g, best->ascent}; }
  if (weight == 700) { const Entry700 *best = &table700[0]; float d = 1e9f; for (auto &e : table700) { float x = e.px > px ? e.px - px : px - e.px; if (x < d) { d = x; best = &e; } } return {best->g, best->ascent}; }
  return {nullptr, 0};
}
